const PAGE="<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#102527\"><title>SpaceBGM2｜音の冒険</title><meta name=\"description\" content=\"仲間がダンジョンを旅し、その冒険が音楽になる放置RPG。\"><link rel=\"icon\" href=\"/favicon.svg\"><style>\n:root{color-scheme:dark;--bg:#0b1519;--panel:#142327;--line:#2d3c3e;--ink:#edf2e6;--muted:#a1b1af;--lime:#c0ee97;--gold:#e8c77b;--cyan:#a9dce0;--danger:#e7a696}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Noto Sans JP\",sans-serif}button,input{font:inherit}button{cursor:pointer;min-height:44px;border:1px solid var(--line);border-radius:12px;background:#203135;color:var(--ink);padding:10px 16px;transition:background .2s,transform .2s}button:hover:not(:disabled){background:#314846;transform:translateY(-1px)}button:disabled{cursor:default;opacity:.45}button:focus-visible,input:focus-visible{outline:3px solid var(--cyan);outline-offset:3px}button.primary{background:var(--lime);color:#18301e;border-color:var(--lime);font-weight:700}button.primary:hover{background:#d2f7b0}button.small{padding:8px 12px}h1,h2,h3,p{margin:0}h2{font-size:19px;font-weight:600}small,.smalltext{font-size:14px;color:var(--muted)}.caps{font:12px/1.4 ui-monospace,monospace;letter-spacing:2px;color:var(--muted)}.shell{max-width:1440px;margin:auto;padding:28px 40px 24px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:28px}.brand{display:flex;align-items:center;gap:14px}.brandmark{color:var(--lime);font-size:32px}.brand h1{font:600 25px/1.3 Georgia,\"Yu Mincho\",serif}.brand .caps{margin-top:5px}.wallet{display:flex;gap:12px}.wallet>div{border:1px solid var(--line);border-radius:12px;padding:8px 16px;min-width:120px}.wallet b{font:600 20px/1.3 ui-monospace,monospace;display:block}.wallet small{font-size:12px}.wallet .gold{color:var(--gold)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px}.scene-card{border:1px solid var(--line);border-radius:20px;overflow:hidden;background:#132629}.scene-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 24px;border-bottom:1px solid var(--line)}.scene-head h2{font:600 24px/1.4 Georgia,\"Yu Mincho\",serif}.scene-head small{display:block;margin-top:3px}.floor{border:1px solid #486257;padding:6px 12px;border-radius:8px;color:var(--lime);font-family:ui-monospace,monospace;white-space:nowrap}.scene{position:relative;height:390px;overflow:hidden;background-color:#133439;background-image:linear-gradient(to top,rgba(8,20,25,.7),transparent 55%),url('data:image/webp;base64,');background-size:cover;background-position:center 60%;transition:filter 1s}.scene[data-zone=cave]{filter:hue-rotate(35deg) saturate(.85)}.scene[data-zone=castle]{filter:hue-rotate(85deg) saturate(.6)}.scene-top{position:absolute;top:20px;left:24px;right:24px;display:flex;justify-content:space-between;gap:8px}.badge{font-size:14px;background:rgba(10,24,27,.82);border:1px solid #526963;padding:6px 12px;border-radius:8px;backdrop-filter:blur(8px)}.badge.phase{color:var(--gold)}.actors{position:absolute;bottom:78px;left:26%;right:17%;display:flex;align-items:flex-end;justify-content:space-between;gap:20px}.party{display:flex;align-items:flex-end;gap:8px;position:relative;animation:walk 1.5s ease-in-out infinite}.sprite{font-size:72px;line-height:1.2;filter:drop-shadow(0 6px 3px #08141e);display:block;transform-origin:bottom}.cat{font-size:42px;display:none}.enemy{font-size:64px;line-height:1.3;animation:float 2s ease-in-out infinite;min-width:90px;text-align:center}.actorlabel{display:block;text-align:center;color:white;text-shadow:0 2px 4px black;font-size:14px}.scene[data-event=battle] .party,.scene[data-event=boss] .party{animation:battle 1s ease-in-out infinite}.scene[data-running=false] .party,.scene[data-running=false] .enemy{animation-play-state:paused}.scene-bottom{position:absolute;bottom:18px;left:24px;right:24px;display:flex;justify-content:space-between;gap:16px;font-size:14px;text-shadow:0 1px 4px #000}.scene-bottom time{font-family:ui-monospace,monospace;color:var(--cyan)}.journey{padding:20px 24px;background:#15282a}.journey-label{display:flex;justify-content:space-between;font-size:14px;color:var(--muted);margin-bottom:10px}.progress{height:7px;border-radius:8px;background:#2b4240;overflow:hidden}.progress i{display:block;height:100%;width:0;background:var(--lime);transition:width .3s}.milestones{display:flex;justify-content:space-between;margin-top:12px;font-size:12px;color:var(--muted)}.scene-foot{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-top:1px solid var(--line);gap:12px}.scene-foot p{font-size:14px;color:var(--muted)}.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:20px}.right{display:flex;flex-direction:column;gap:20px}.card-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.zone-list{display:flex;flex-direction:column;gap:10px}.zone{display:grid;grid-template-columns:40px 1fr auto;gap:10px;text-align:left;width:100%;padding:12px;border-radius:12px}.zone.active{border-color:var(--lime);background:#243c31}.zone .icon{font-size:26px}.zone b{display:block;font-size:16px}.zone small{font-size:12px;display:block;line-height:1.7}.zone .check{color:var(--lime);font-size:14px;align-self:center}.hero{display:flex;align-items:center;gap:14px;margin-bottom:16px}.portrait{font-size:40px;line-height:1.4}.hero h3{font-size:18px}.level{color:var(--lime);font-family:ui-monospace,monospace}.stats{display:flex;justify-content:space-between;font-size:14px;color:var(--muted);padding:12px 0;border-top:1px solid var(--line)}.upgrade{width:100%;display:flex;justify-content:space-between;gap:8px}.hire{width:100%;text-align:left;margin-top:12px}.hire small{display:block;font-size:12px}.bottom{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;margin-top:24px}.logs{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:0}.logs li{padding:10px 0;border-bottom:1px solid var(--line);font-size:14px;display:flex;align-items:flex-start;gap:12px}.logs li:last-child{border:0}.logs .logtime{font:12px/1.8 ui-monospace,monospace;color:var(--muted);min-width:42px}.logs .logicon{min-width:20px}.music h2{margin-bottom:4px}.music-top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.disc{font-size:25px;color:var(--lime)}.music-controls{display:flex;gap:10px;align-items:center}.music-controls button{flex:1}.equalizer{display:flex;gap:3px;height:24px;align-items:center;padding:0 4px}.equalizer i{width:3px;height:5px;background:var(--lime);border-radius:1px}.music[data-playing=true] .equalizer i{animation:eq .7s ease-in-out infinite alternate}.equalizer i:nth-child(2){animation-delay:.2s!important}.equalizer i:nth-child(3){animation-delay:.4s!important}.equalizer i:nth-child(4){animation-delay:.1s!important}.volume{margin-top:16px}.volume label{display:flex;justify-content:space-between;font-size:14px;color:var(--muted)}input[type=range]{width:100%;accent-color:var(--lime);min-height:40px}.notes{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:12px;font-size:12px;color:var(--muted)}.notice{display:none;border:1px solid #52644b;background:#233829;padding:16px 20px;border-radius:14px;margin-bottom:20px;font-size:14px;align-items:center;justify-content:space-between;gap:16px}.notice.error{background:#342825;border-color:#77554a}.notice button{flex-shrink:0}.status{font-size:12px;color:var(--muted)}footer{display:flex;justify-content:space-between;gap:12px;margin-top:24px;color:var(--muted);font-size:12px}.toast{position:fixed;bottom:28px;left:50%;transform:translateX(-50%);border:1px solid var(--line);border-radius:12px;background:#223936;padding:12px 20px;box-shadow:0 12px 40px #0008;z-index:5;max-width:90vw;font-size:14px;display:none}@keyframes walk{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-6px) rotate(2deg)}}@keyframes battle{0%,100%{transform:translateX(0)}50%{transform:translateX(16px)}}@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}@keyframes eq{to{height:24px}}@media(max-width:1000px){.shell{padding:24px}.layout,.bottom{grid-template-columns:minmax(0,1fr) 280px}.scene{height:350px}.scene-head{padding:16px}.scene-head h2{font-size:22px}.actors{left:20%;right:10%}}@media(max-width:760px){.shell{padding:18px 16px}.layout,.bottom{grid-template-columns:1fr;gap:16px}.bottom{margin-top:16px}.right{gap:16px}.brand h1{font-size:21px}.brandmark{font-size:26px}.brand .caps{font-size:10px;letter-spacing:1px}.brand{gap:8px}header{align-items:flex-start;margin-bottom:18px;gap:10px}.wallet{gap:6px}.wallet>div{min-width:64px;padding:7px 9px}.wallet b{font-size:17px}.wallet small{font-size:10px}.scene{height:330px}.scene-head h2{font-size:22px}.scene-head small{font-size:12px}.scene-top{left:16px;right:16px;top:16px}.scene-bottom{left:16px;right:16px;font-size:12px}.actors{bottom:80px;left:18%;right:10%}.sprite{font-size:60px}.enemy{font-size:54px}.scene-foot,.journey{padding:16px}.scene-foot p{max-width:65%}.zone-list{display:grid;grid-template-columns:1fr;gap:8px}.right .card:first-child{order:1}.bottom .music{order:-1}footer{flex-direction:column;gap:4px}.notice{align-items:flex-start}.milestones{font-size:12px}.caps{font-size:12px}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n</style></head><body><div class=\"shell\"><header><div class=\"brand\"><span class=\"brandmark\" aria-hidden=\"true\">✦</span><div><h1>音の冒険</h1><p class=\"caps\">SPACEBGM2 / IDLE RPG</p></div></div><div class=\"wallet\"><div><small>ゴールド</small><b class=\"gold\" id=\"coins\">— G</b></div><div><small>星のかけら</small><b id=\"crystals\">— ✧</b></div></div></header><div class=\"notice\" id=\"offline\" role=\"status\"><div id=\"offlineText\"></div><button class=\"small\" id=\"dismissOffline\">閉じる</button></div><div class=\"notice error\" id=\"error\" role=\"alert\"><p id=\"errorText\"></p><button class=\"small\" id=\"retry\">再試行</button></div><main><div class=\"layout\"><section class=\"scene-card\" aria-label=\"冒険の様子\"><div class=\"scene-head\"><div><h2 id=\"zoneName\">蛍火の森</h2><small id=\"zoneSubtitle\">小さな冒険のはじまり</small></div><span class=\"floor\" id=\"floor\">1 / 10 F</span></div><div class=\"scene\" id=\"scene\" data-zone=\"forest\" data-event=\"travel\"><div class=\"scene-top\"><span class=\"badge\" id=\"stateBadge\">冒険の記録を読込中</span><span class=\"badge phase\" id=\"eventBadge\">探索</span></div><div class=\"actors\"><div class=\"party\"><div><span class=\"sprite\" role=\"img\" aria-label=\"冒険者ルウ\">🧙</span><span class=\"actorlabel\">ルウ</span></div><div id=\"catActor\"><span class=\"sprite cat\" role=\"img\" aria-label=\"仲間の猫トム\">🐈</span><span class=\"actorlabel cat\" id=\"catLabel\">トム</span></div></div><div><span class=\"enemy\" id=\"enemy\" role=\"img\" aria-label=\"探索中\">✨</span><span class=\"actorlabel\" id=\"enemyName\">蛍の道</span></div></div><div class=\"scene-bottom\"><span id=\"narration\">仲間が自動で歩き、戦い、お宝を探す。</span><time id=\"clock\"></time></div></div><div class=\"journey\"><div class=\"journey-label\"><span id=\"journeyText\">次の場所へ</span><span id=\"remaining\">— 秒</span></div><div class=\"progress\" role=\"progressbar\" aria-label=\"次の冒険イベントまで\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\" id=\"progress\"><i id=\"bar\"></i></div><div class=\"milestones\"><span>探索</span><span>戦闘・宝箱</span><span>10F ボス</span></div></div><div class=\"scene-foot\"><p>冒険は自動で進む。まずは仲間を育てよう。</p><button id=\"toggle\" disabled>ひと休み</button></div></section><aside class=\"right\"><section class=\"card\"><div class=\"card-header\"><h2>冒険の行き先</h2><span class=\"caps\">MAP</span></div><div class=\"zone-list\" id=\"zones\"></div></section><section class=\"card\"><div class=\"card-header\"><h2>旅の仲間</h2><span class=\"caps\">PARTY</span></div><div class=\"hero\"><span class=\"portrait\" aria-hidden=\"true\">🧙</span><div><h3>ルウ <span class=\"level\" id=\"level\">Lv.1</span></h3><small>旋律を探す、小さな冒険者</small></div></div><div class=\"stats\"><span>ボスに挑む目安</span><b id=\"recommended\">Lv.2</b></div><button class=\"primary upgrade\" id=\"train\" disabled><span>ルウを育てる</span><span id=\"trainCost\">40 G</span></button><button class=\"hire\" id=\"hire\" disabled>🐈 トムを仲間にする <small id=\"hireText\">120 G · 冒険の報酬が20％増える</small></button></section></aside></div><div class=\"bottom\"><section class=\"card\"><div class=\"card-header\"><h2>冒険の記録</h2><span class=\"status\" id=\"saveStatus\">読込中</span></div><ol class=\"logs\" id=\"logs\"><li>仲間の冒険を準備しています。</li></ol></section><section class=\"card music\" id=\"music\" data-playing=\"false\"><div class=\"music-top\"><div><h2>旅の音楽</h2><small id=\"musicMood\">蛍火の森 · 探索</small></div><span class=\"disc\" aria-hidden=\"true\">♫</span></div><div class=\"music-controls\"><button id=\"sound\" class=\"primary\" aria-pressed=\"false\">音楽を再生</button><div class=\"equalizer\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></div></div><div class=\"volume\"><label for=\"volume\"><span>音量</span><span id=\"volumeLabel\">35％</span></label><input type=\"range\" id=\"volume\" min=\"0\" max=\"100\" value=\"35\"></div><div class=\"notes\"><span id=\"tempo\">88 BPM</span><span>場面に合わせて、音が重なる</span></div></section></div></main><footer><span>SpaceBGM2 · 試作版 0.1</span><span>進行は自動保存 · 閉じている間も最大8時間分の報酬</span></footer></div><div class=\"toast\" id=\"toast\" role=\"status\"></div>\n<script>\n'use strict';\nconst $=id=>document.getElementById(id);\nlet snapshot=null,offset=0,busy=false,loading=false,firstLoad=true,toastTimer;\nconst labels={travel:'探索',battle:'戦闘',treasure:'宝箱',boss:'ボス戦'};\nconst icons={travel:'🍃',battle:'⚔',treasure:'✧',boss:'♛',retreat:'↩',level:'✦'};\nfunction toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3500);}\nfunction format(n){return new Intl.NumberFormat('ja-JP').format(n);}\nfunction render(){\n if(!snapshot)return;\n const g=snapshot.game,z=snapshot.zones.find(z=>z.id===g.zone),event=snapshot.event;\n $('coins').textContent=format(g.coins)+' G';$('crystals').textContent=g.crystals+' ✧';$('level').textContent='Lv.'+g.level;\n $('zoneName').textContent=z.name;$('zoneSubtitle').textContent=z.subtitle;$('floor').textContent=g.floor+' / 10 F';\n $('scene').dataset.zone=g.zone;$('scene').dataset.event=event;$('scene').dataset.running=g.running;\n $('stateBadge').textContent=g.running?'自動で冒険中':'焚き火でひと休み';$('eventBadge').textContent=g.running?labels[event]:'休憩';\n $('enemy').textContent=!g.running?'🔥':event==='boss'?'🐉':event==='battle'?(g.zone==='forest'?'🟢':g.zone==='cave'?'🦇':'👻'):event==='treasure'?'🎁':'✨';\n $('enemyName').textContent=!g.running?'ひと休み':event==='boss'?z.boss:event==='battle'?z.enemy:event==='treasure'?'古い宝箱':'奥へ続く道';\n $('enemy').setAttribute('aria-label',$('enemyName').textContent);\n $('narration').textContent=!g.running?'旅を再開すると、冒険が進む。':event==='boss'?'ダンジョンの主が待ち構えている。':event==='battle'?'ルウは武器を構えた。':event==='treasure'?'宝箱から、小さな旋律が聞こえる。':'ルウは光を頼りに奥へ進む。';\n $('toggle').textContent=g.running?'ひと休み':'冒険を再開';$('toggle').disabled=busy;\n $('trainCost').textContent=snapshot.trainCost+' G';$('train').disabled=busy||g.coins<snapshot.trainCost||g.level>=30;\n $('recommended').textContent='Lv.'+(z.level+1);$('hire').disabled=busy||g.companion||g.coins<120;\n $('hireText').textContent=g.companion?'トムが同行中 · 報酬が20％増える':'120 G · 冒険の報酬が20％増える';\n document.querySelectorAll('.cat').forEach(e=>e.style.display=g.companion?'block':'none');\n $('zones').replaceChildren();snapshot.zones.forEach(zone=>{const b=document.createElement('button');b.className='zone'+(zone.id===g.zone?' active':'');b.disabled=busy||!zone.unlocked;b.setAttribute('aria-pressed',String(zone.id===g.zone));const icon=document.createElement('span');icon.className='icon';icon.textContent=zone.icon;const title=document.createElement('span');const strong=document.createElement('b');strong.textContent=zone.name;const meta=document.createElement('small');meta.textContent=zone.unlocked?'Lv.'+zone.level+'～ · 踏破 '+g.clears[zone.id]+'回':zone.id==='cave'?'森を踏破 ＋ Lv.3で解放':'洞窟を踏破 ＋ Lv.5で解放';title.append(strong,meta);const mark=document.createElement('span');mark.className='check';mark.textContent=zone.id===g.zone?'探索中':zone.unlocked?'':'🔒';b.append(icon,title,mark);b.onclick=()=>command({type:'zone',zone:zone.id});$('zones').append(b);});\n $('logs').replaceChildren();g.logs.slice(0,5).forEach(l=>{const li=document.createElement('li'),time=document.createElement('time'),icon=document.createElement('span'),text=document.createElement('span');time.className='logtime';time.textContent=new Date(l.at).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tokyo'});icon.className='logicon';icon.textContent=icons[l.kind]||'✦';text.textContent=l.text;li.append(time,icon,text);$('logs').append(li);});\n $('musicMood').textContent=z.name+' · '+(g.running?labels[event]:'休憩');$('tempo').textContent=z.bpm+' BPM';music.targetBpm=z.bpm;music.mood=g.running?event:'travel';music.targetZone=g.zone;\n drawProgress();\n}\nfunction drawProgress(){const now=Date.now()+offset;$('clock').textContent=new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Tokyo'});if(!snapshot)return;const g=snapshot.game;const p=g.running?Math.min(1,Math.max(0,(now-g.lastAt)/8000)):0;$('bar').style.width=(p*100)+'%';$('progress').setAttribute('aria-valuenow',String(Math.round(p*100)));$('remaining').textContent=g.running?Math.max(0,Math.ceil(8-p*8))+'秒':'休憩中';$('journeyText').textContent=g.running?'この階の探索が終わるまで':'冒険を再開して続きを進める';}\nasync function load(){if(loading||busy||document.hidden)return;loading=true;try{const r=await fetch('/api/game',{cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'記録を読み込めませんでした。');offset=d.serverNow-Date.now();snapshot=d;render();$('error').style.display='none';$('saveStatus').textContent='保存済み';if(firstLoad){if(d.report.seconds>=25){const minutes=Math.max(1,Math.floor(d.report.seconds/60));$('offlineText').textContent='おかえり！ 留守中の冒険で '+format(d.report.coins)+'G、星のかけら'+d.report.crystals+'個を獲得。'+(d.report.capped?'最大8時間分を記録したよ。':(d.report.seconds<60?d.report.seconds+'秒':minutes+'分')+'ほど旅していたよ。');$('offline').style.display='flex';}firstLoad=false;}}catch(e){$('errorText').textContent=e.message;$('error').style.display='flex';$('saveStatus').textContent='接続を確認中';}finally{loading=false;}}\nasync function command(action){if(busy||!snapshot)return;busy=true;render();try{const r=await fetch('/api/game',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action)});const d=await r.json();if(!r.ok)throw new Error(d.error||'操作できませんでした。');offset=d.serverNow-Date.now();snapshot=d;$('error').style.display='none';$('saveStatus').textContent='保存済み';if(action.type==='train')toast('ルウがLv.'+d.game.level+'になった！');if(action.type==='hire')toast('トムが旅の仲間になった！');if(action.type==='zone')toast('新しい場所へ出発！');return {zone:d.game.zone,level:d.game.level,coins:d.game.coins,running:d.game.running};}catch(e){toast(e.message);throw e;}finally{busy=false;render();}}\n// A single beat clock; changes apply on the next bar and never reset phase.\nconst music={ctx:null,master:null,playing:false,step:0,next:0,bpm:88,targetBpm:88,mood:'travel',zone:'forest',targetZone:'forest',timer:null,generation:0,\n async toggle(){this.generation++;const generation=this.generation;if(this.playing){this.playing=false;clearInterval(this.timer);if(this.master){this.master.gain.cancelScheduledValues(this.ctx.currentTime);this.master.gain.setTargetAtTime(0,this.ctx.currentTime,.06);const ctx=this.ctx;setTimeout(()=>{if(!this.playing&&this.generation===generation)ctx.suspend().catch(()=>{});},250);}}else{const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast('このブラウザでは音楽を再生できません。');return;}try{if(!this.ctx){this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=0;this.master.connect(this.ctx.destination);}await this.ctx.resume();if(generation!==this.generation)return;if(this.ctx.state!=='running'){toast('再生ボタンをもう一度押してな。');return;}this.playing=true;this.next=this.ctx.currentTime+.08;this.volume();this.timer=setInterval(()=>this.schedule(),30);this.schedule();}catch{toast('音楽を開始できませんでした。もう一度試してください。');}}\n $('sound').textContent=this.playing?'音楽を止める':'音楽を再生';$('sound').setAttribute('aria-pressed',String(this.playing));$('music').dataset.playing=this.playing;},\n volume(){if(this.master){this.master.gain.cancelScheduledValues(this.ctx.currentTime);this.master.gain.setTargetAtTime(this.playing?Number($('volume').value)/100*.32:0,this.ctx.currentTime,.05);}},\n tone(freq,time,duration,gain,type='sine'){const o=this.ctx.createOscillator(),a=this.ctx.createGain();o.type=type;o.frequency.value=freq;a.gain.setValueAtTime(.0001,time);a.gain.exponentialRampToValueAtTime(Math.max(.001,gain),time+.02);a.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(a);a.connect(this.master);o.start(time);o.stop(time+duration+.04);o.onended=()=>{o.disconnect();a.disconnect();};},\n noise(time,duration,gain){const b=this.ctx.createBuffer(1,Math.ceil(this.ctx.sampleRate*duration),this.ctx.sampleRate),v=b.getChannelData(0);for(let i=0;i<v.length;i++)v[i]=(Math.random()*2-1)*(1-i/v.length);const s=this.ctx.createBufferSource(),a=this.ctx.createGain(),f=this.ctx.createBiquadFilter();s.buffer=b;f.type='highpass';f.frequency.value=700;a.gain.setValueAtTime(gain,time);a.gain.exponentialRampToValueAtTime(.0001,time+duration);s.connect(f);f.connect(a);a.connect(this.master);s.start(time);s.onended=()=>{s.disconnect();f.disconnect();a.disconnect();};},\n schedule(){if(!this.playing||this.ctx.state!=='running')return;if(this.next<this.ctx.currentTime-.2)this.next=this.ctx.currentTime+.05;while(this.next<this.ctx.currentTime+.18){const i=this.step%32;if(i%8===0){this.bpm=this.targetBpm;this.zone=this.targetZone;}const beat=60/this.bpm,bar=Math.floor(i/8);const roots=this.zone==='forest'?[64,60,62,59]:this.zone==='cave'?[57,53,55,52]:[62,58,60,57];const root=roots[bar];const chord=[root,root+3,root+7];const hz=n=>440*Math.pow(2,(n-69)/12);if(i%4===0)this.tone(hz(root-24),this.next,beat*1.3,.28,'triangle');if(i%8===0)chord.forEach(n=>this.tone(hz(n),this.next,beat*3.6,.055,'sine'));if(i%3===0||this.mood==='treasure')this.tone(hz(chord[(i+bar)%3]+12),this.next,beat*.85,.12,'sine');if(this.mood==='battle'||this.mood==='boss'){if(i%2===0)this.noise(this.next,.055,.08);if(i%8===4)this.noise(this.next,.13,.16);if(this.mood==='boss'&&i%2===0)this.tone(hz(chord[(i/2)%3|0]),this.next,beat*.42,.12,'triangle');}this.next+=beat/2;this.step++;}}};\n$('sound').onclick=()=>music.toggle();$('volume').oninput=()=>{$('volumeLabel').textContent=$('volume').value+'％';music.volume();};\n$('train').onclick=()=>command({type:'train'}).catch(()=>{});$('hire').onclick=()=>command({type:'hire'}).catch(()=>{});$('toggle').onclick=()=>command({type:'toggle'}).catch(()=>{});$('retry').onclick=()=>load();$('dismissOffline').onclick=()=>{$('offline').style.display='none';};\nsetInterval(drawProgress,250);setInterval(load,2500);document.addEventListener('visibilitychange',()=>{if(!document.hidden){firstLoad=true;load();if(music.playing&&music.ctx.state==='running')music.next=music.ctx.currentTime+.06;}});load();\nif(document.modelContext?.registerTool){for(const tool of [{name:'get_adventure',description:'Read the visible adventure, gold, level and destination.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot?{zone:snapshot.game.zone,level:snapshot.game.level,coins:snapshot.game.coins,running:snapshot.game.running}:{loading:true}},{name:'train_adventurer',description:'Spend the displayed gold cost to increase Ruu by one level.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>command({type:'train'})},{name:'choose_dungeon',description:'Travel to an unlocked dungeon and begin on floor one.',inputSchema:{type:'object',properties:{zone:{type:'string',enum:['forest','cave','castle']}},required:['zone'],additionalProperties:false},execute:input=>{if(!input||!['forest','cave','castle'].includes(input.zone))throw new Error('Invalid dungeon');return command({type:'zone',zone:input.zone});}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}\n</script></body></html>\n";
const STEP_MS = 8000;
const OFFLINE_LIMIT = 8 * 60 * 60 * 1000;
const ZONES = [
 {id:'forest',name:'蛍火の森',subtitle:'小さな冒険のはじまり',level:1,mult:1,icon:'🌲',enemy:'スライム',boss:'森の守り人',bpm:88},
 {id:'cave',name:'水晶の洞窟',subtitle:'水晶が奏でる深い響き',level:3,mult:2,icon:'💎',enemy:'洞窟コウモリ',boss:'水晶ゴーレム',bpm:96},
 {id:'castle',name:'月影の古城',subtitle:'忘れられた旋律を探して',level:5,mult:3,icon:'🏰',enemy:'影の騎士',boss:'月影の竜',bpm:108}
];
function initialGame(now = Date.now()) {
 return {version:1,coins:60,crystals:0,level:1,companion:false,zone:'forest',floor:1,clears:{forest:0,cave:0,castle:0},running:true,lastAt:now,steps:0,totalCoins:0,logs:[{id:0,text:'ルウは蛍火の森へ出発した。',kind:'travel',at:now}]};
}
function unlocked(g,id) {
 const i=ZONES.findIndex(z=>z.id===id);
 return i>=0 && g.level>=ZONES[i].level && (i===0 || g.clears[ZONES[i-1].id]>0);
}
function cost(g) { return 40 * g.level; }
function eventFor(g) { return g.floor===10 ? 'boss' : g.floor%4===0 ? 'treasure' : g.floor%2===0 ? 'battle' : 'travel'; }
function log(g,text,kind,at) { g.logs.unshift({id:g.steps,text,kind,at}); g.logs=g.logs.slice(0,24); }
function advanceGame(input,now=Date.now()) {
 const g=structuredClone(input);
 const elapsed=Math.max(0,now-g.lastAt);
 const offline=Math.max(0,elapsed-20000);
 const report={seconds:Math.floor(Math.min(offline,OFFLINE_LIMIT)/1000),coins:0,crystals:0,steps:0,capped:elapsed>OFFLINE_LIMIT};
 if(!g.running) {g.lastAt=now;return {game:g,report};}
 // Accrue at most eight hours; retain a sub-step remainder for a smooth phase.
 if(elapsed>OFFLINE_LIMIT) g.lastAt=now-OFFLINE_LIMIT;
 const n=Math.floor(Math.max(0,now-g.lastAt)/STEP_MS);
 const beforeCoins=g.coins, beforeCrystals=g.crystals;
 for(let i=0;i<n;i++) {
  g.lastAt+=STEP_MS;g.steps++;
  const z=ZONES.find(z=>z.id===g.zone),event=eventFor(g);
  const reward=Math.round((event==='boss'?70:event==='treasure'?25:event==='battle'?15:8)*z.mult*(g.companion?1.2:1));
  if(event==='boss' && g.level < z.level+1) {
   log(g,z.boss+'は手強い！拠点で休み、再び探索へ。','retreat',g.lastAt);g.floor=1;continue;
  }
  g.coins+=reward;g.totalCoins+=reward;
  if(event==='boss') {g.clears[g.zone]++;g.crystals+=z.mult;log(g,z.boss+'を倒した！ '+reward+'Gと星のかけら'+z.mult+'個。','boss',g.lastAt);g.floor=1;}
  else { log(g,event==='treasure'?'宝箱を発見！ '+reward+'G。':event==='battle'?z.enemy+'を倒した！ '+reward+'G。':'道を進み、'+reward+'Gを見つけた。',event,g.lastAt);g.floor++; }
 }
 report.coins=g.coins-beforeCoins;report.crystals=g.crystals-beforeCrystals;report.steps=n;
 return {game:g,report};
}
function applyAction(input,action,now=Date.now()) {
 const {game:g}=advanceGame(input,now);
 switch(action.type) {
  case 'train': {const price=cost(g);if(g.coins<price) throw new Error('ゴールドが足りません。');if(g.level>=30)throw new Error('レベルは上限です。');g.coins-=price;g.level++;log(g,'ルウがLv.'+g.level+'に成長した。','level',now);break;}
  case 'hire': if(g.companion)throw new Error('トムはもう仲間です。');if(g.coins<120)throw new Error('ゴールドが足りません。');g.coins-=120;g.companion=true;log(g,'白キジ猫のトムが仲間になった！ 報酬が20％増える。','level',now);break;
  case 'zone': if(!unlocked(g,action.zone))throw new Error('まだこの場所には行けません。');if(action.zone!==g.zone){g.zone=action.zone;g.floor=1;g.lastAt=now;log(g,ZONES.find(z=>z.id===g.zone).name+'へ旅立った。','travel',now);}break;
  case 'toggle':g.running=!g.running;g.lastAt=now;log(g,g.running?'冒険を再開した。':'焚き火でひと休み。','travel',now);break;
  default:throw new Error('不明な操作です。');
 }
 return g;
}
function publicGame(g,now,report={}) {return {game:g,zones:ZONES.map(z=>({...z,unlocked:unlocked(g,z.id)})),trainCost:cost(g),serverNow:now,event:eventFor(g),report};}

// PAGE and game engine are bundled by build.mjs.
const KEY='spacebgm2/owner-game-v1.json';
const headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers});}
async function readGame(bucket,now){const object=await bucket.get(KEY);return {game:object?await object.json():initialGame(now),etag:object?.etag};}
export default {
 async fetch(request,env) {
  const url=new URL(request.url);
  if(url.pathname==='/')return new Response(PAGE,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}});
  if(url.pathname==='/favicon.svg')return new Response('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="#102527"/><path d="M16 4 19 12 28 16 19 19 16 28 12 19 4 16 12 12Z" fill="#b8ee91"/></svg>',{headers:{'Content-Type':'image/svg+xml'}});
  if(url.pathname!=='/api/game')return json({error:'Not found'},404);
  if(!['GET','POST'].includes(request.method))return json({error:'Method not allowed'},405);
  if(request.method==='POST') {
   if(request.headers.get('Origin')!==url.origin)return json({error:'このページから操作してください。'},403);
   if(!request.headers.get('Content-Type')?.includes('application/json'))return json({error:'Invalid content type'},415);
  }
  if(!env.BUCKET)return json({error:'冒険の記録に接続できません。少し待ってから再試行してください。'},503);
  let action;
  if(request.method==='POST'){try {const text=await request.text();if(text.length>500)return json({error:'Request too large'},413);action=JSON.parse(text);}catch{return json({error:'Invalid JSON'},400);}}
  try {
   for(let attempt=0;attempt<3;attempt++) {
    const now=Date.now();const {game:old,etag}=await readGame(env.BUCKET,now);
    const advanced=advanceGame(old,now);let game=advanced.game;
    if(action){try{game=applyAction(game,action,now);}catch(e){return json({error:e.message},400);}}
    if(!etag||action||game.lastAt!==old.lastAt){
     const stored=await env.BUCKET.put(KEY,JSON.stringify(game),{httpMetadata:{contentType:'application/json'},onlyIf:etag?{etagMatches:etag}:{etagDoesNotMatch:'*'}});
     if(!stored)continue;
    }
    return json(publicGame(game,now,advanced.report));
   }
   return json({error:'ほかの画面で更新されました。もう一度操作してください。'},409);
  } catch(e) {console.error('Game persistence unavailable',e?.message);return json({error:'冒険の記録を読み込めませんでした。再試行してください。'},503);}
 }
};
